import { ChangeDetectionStrategy, Component } from '@angular/core';
import { MakeService } from '../../services/make-service';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-edit-make',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './edit-make.html',
  styleUrl: './edit-make.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EditMake {
makeForm! : FormGroup;
makeId! : number;
isLoading = true;

constructor(
    private fb: FormBuilder,
    private service: MakeService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

    ngOnInit(): void {
    this.makeForm = this.fb.group({
      name: ['', Validators.required],
      price: [''],
    });
   const id = Number(this.route.snapshot.paramMap.get('id'));
    if (id) {
      this.makeId = id;
      this.service.getProductByID(id).subscribe(product => {
        this.makeForm.patchValue(product); 
        this.isLoading = false;
      });
    } else {
      this.isLoading = false;
    }
    }
    onCancel(){
    this.resetForm();
    this.router.navigate(['/make']);
  }
   onSubmit() {
  if (this.makeForm.invalid) 
    return;

   const dto = {
    ...this.makeForm.value,
   }

  console.log("Submitting make:", dto);

  this.service.updateProduct(this.makeId, dto).subscribe({
    next: () => {
      alert('✅ Product updated successfully');
      this.resetForm();
    },
    error: (err) => {
      console.error('❌ Upload failed', err);
      alert(err.error?.message || 'Upload failed. Please try again.');
    }
  });

  this.router.navigate(['/make'])
}


  private resetForm() {
    this.makeForm.reset();
  }
}
